   const addMessage = (id: string, message: string) => { if (!user || !message.trim()) return; const nextMessage = { id: `msg-${Date.now()}`, user_id: user.id, username: user.username, message }; updateMatch(id, { messages: [...(matches.find(item => item.id === id)?.messages || []), nextMessage] }); if (supabaseEnabled && supabase) void supabase.from('match_messages').insert({ match_id: id, user_id: user.id, username: user.username, message }).then(({ error }) => { if (error) console.error('message save failed', error); }); recordActivity('إرسال رسالة', `أرسل ${user.username} رسالة داخل مباراة`, 'MATCH', user); };
   const openDispute = (matchId: string, subject: string, details: string, files: File[] = []) => { if (!user) return; const created_at = new Date().toISOString(); const item: Dispute = { id: supabaseEnabled ? crypto.randomUUID() : `D-${Date.now().toString().slice(-5)}`, matchId, username: user.username, userId: user.id, subject, details, status: 'OPEN', evidence: files.map(file => file.name), created_at }; setDisputes(old => [item, ...old]); updateMatch(matchId, { status: 'DISPUTE' }); if (supabaseEnabled && supabase) void (async () => { const inserted = await supabase.from('disputes').insert({ id: item.id, match_id: matchId, username: user.username, user_id: user.id, subject, details, status: 'OPEN', created_at }).select('id').single(); if (!inserted.data) return; const evidence: { dispute_id: string; file_path: string; file_url: string; mime_type: string; original_name: string }[] = []; for (const file of files) { const path = `${user.id}/${inserted.data.id}/${crypto.randomUUID()}-${file.name.replace(/[^a-zA-Z0-9._-]/g, '-')}`; const upload = await supabase.storage.from('dispute-evidence').upload(path, file, { upsert: false, contentType: file.type }); if (!upload.error) { const publicFile = supabase.storage.from('dispute-evidence').getPublicUrl(path); evidence.push({ dispute_id: inserted.data.id, file_path: path, file_url: publicFile.data.publicUrl, mime_type: file.type, original_name: file.name }); } } if (evidence.length) await supabase.from('dispute_evidence').insert(evidence); })(); recordActivity('فتح نزاع', `فتح ${user.username} نزاعاً على المباراة ${matchId}`, 'DISPUTE', user); };
