const money = (amount: number) => `$${amount.toFixed(2)}`;
const date = (value: string) => new Intl.DateTimeFormat('ar-MA', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value));
const initials = (value: string) => value.slice(0, 2).toUpperCase();
const statusLabel: Record<string, string> = { PENDING: 'قيد المراجعة', APPROVED: 'معتمد', REJECTED: 'مرفوض', OPEN: 'مفتوح', UNDER_REVIEW: 'قيد التحقيق', RESOLVED: 'تم الحل', DISPUTE: 'نزاع', PLAYING: 'جارية', COMPLETED: 'مكتملة', OPEN_MATCH: 'متاحة', UPCOMING: 'قادمة', LIVE: 'مباشرة', CANCELLED: 'ملغاة' };
function StatusBadge({ status }: { status: string }) { const tone = ['APPROVED', 'RESOLVED', 'COMPLETED'].includes(status) ? 'success' : ['REJECTED'].includes(status) ? 'danger' : ['PENDING', 'UNDER_REVIEW', 'DISPUTE'].includes(status) ? 'warning' : 'info'; return <span className={`status-badge status-${tone}`}>{statusLabel[status] || status}</span>; }
function Notice({ children, type = 'success' }: { children: ReactNode; type?: 'success' | 'error' }) { return <div className={`notice ${type === 'error' ? 'notice-error' : ''}`}><AlertCircle className="h-4 w-4 shrink-0" />{children}</div>; }
function Empty({ icon: Icon = Activity, text }: { icon?: typeof Activity; text: string }) { return <div className="empty-state"><Icon className="mx-auto mb-3 h-9 w-9 text-zinc-700" /><p>{text}</p></div>; }
function Modal({ children, onClose, wide = false }: { children: ReactNode; onClose: () => void; wide?: boolean }) { return <div className="modal-backdrop"><div className={`modal-card ${wide ? 'max-w-2xl' : 'max-w-md'}`}><button className="modal-close" onClick={onClose} aria-label="إغلاق"><X className="h-5 w-5" /></button>{children}</div></div>; }

function PublicNavbar() {
  const { user, logout } = useArena(); const [, setLocation] = useLocation(); const [mobile, setMobile] = useState(false); const [rechargeOpen, setRechargeOpen] = useState(false);
  const links = [{ href: '/matches', label: 'المباريات', icon: Swords }, { href: '/tournaments', label: 'البطولات', icon: Trophy }, { href: '/leaderboard', label: 'لوحة الصدارة', icon: BarChart3 }, { href: '/momentum', label: 'نبض الساحة', icon: Zap }];
  return <>
    <header className="site-header"><div className="shell nav-inner"><Link href="/" className="brand"><span className="brand-mark"><Swords className="h-5 w-5" /></span><span><strong>eFootball <em>ARENA</em></strong><small>منصة المنافسة الآمنة</small></span></Link><nav className="desktop-nav">{links.map(({ href, label, icon: Icon }) => <Link href={href} key={href} className="nav-link"><Icon className="h-4 w-4" />{label}</Link>)}{user?.role === 'ADMIN' && <Link href="/admin" className="nav-admin"><ShieldCheck className="h-4 w-4" />لوحة الإدارة</Link>}</nav><div className="nav-actions"><span className="language-pill">العربية الفصحى</span>{user ? <><button className="balance-chip" onClick={() => setRechargeOpen(true)}><Wallet className="h-4 w-4" /><span>الرصيد<strong>{user.role === 'ADMIN' ? 'إدارة' : money(user.balance)}</strong></span><Plus className="h-4 w-4" /></button><button className="icon-button" onClick={() => setLocation('/profile')} aria-label="الملف الشخصي"><UserIcon className="h-4 w-4" /></button><button className="icon-button" onClick={logout} aria-label="تسجيل الخروج"><LogOut className="h-4 w-4" /></button></> : <><Link href="/login" className="text-link">تسجيل الدخول</Link><Link href="/register" className="primary-button small">إنشاء حساب</Link></>}</div><button className="mobile-menu-button" onClick={() => setMobile(!mobile)} aria-label="القائمة"><Menu className="h-5 w-5" /></button></div></header>
     {mobile && <div className="mobile-nav">{links.map(({ href, label, icon: Icon }) => <Link href={href} key={href} onClick={() => setMobile(false)} className="nav-link"><Icon className="h-4 w-4" />{label}</Link>)}{user?.role === 'ADMIN' && <Link href="/admin" onClick={() => setMobile(false)} className="nav-admin"><ShieldCheck className="h-4 w-4" />لوحة الإدارة</Link>}{!user && <Link href="/login" onClick={() => setMobile(false)} className="primary-button">تسجيل الدخول</Link>}</div>}
    {rechargeOpen && user && <RechargeModal onClose={() => setRechargeOpen(false)} />}
  </>;
}
function Footer() { return <footer className="site-footer"><div className="shell footer-inner"><span><strong>eFootball ARENA</strong> منصة مغربية للمنافسة العادلة</span><span>نظام ضمان مالي آمن • دعم متواصل</span></div></footer>; }
function PageTitle({ icon: Icon, title, subtitle, tone = 'green' }: { icon: typeof Swords; title: string; subtitle: string; tone?: string }) { return <div className="page-title"><span className={`page-icon tone-${tone}`}><Icon className="h-6 w-6" /></span><span><h1>{title}</h1><p>{subtitle}</p></span></div>; }
function Field({ label, value, onChange, type = 'text', test, placeholder }: { label: string; value: string; onChange: (value: string) => void; type?: string; test?: string; placeholder?: string }) { return <label className="form-field"><span>{label}</span><input data-testid={test} type={type} value={value} placeholder={placeholder} onChange={event => onChange(event.target.value)} required /></label>; }

function AuthPage({ mode }: { mode: 'login' | 'register' }) {
  const { login, register } = useArena(); const [, setLocation] = useLocation(); const isLogin = mode === 'login'; const [form, setForm] = useState({ login: '', password: '', username: '', email: '', efootball_id: '', whatsapp: '' }); const [error, setError] = useState('');
  const update = (key: keyof typeof form, value: string) => setForm(old => ({ ...old, [key]: value }));
  const submit = async (event: FormEvent) => {
    event.preventDefault();
    if (isLogin) {
      const role = await login(form.login, form.password);
      if (!role) return setError('بيانات الدخول غير صحيحة أو الحساب غير مؤكد.');
      setLocation(role === 'ADMIN' ? '/admin' : '/matches');
      return;
    }
    const result = await register(form);
    if (!result) return setError('تعذر إنشاء الحساب. تحقق من البيانات أو أن البريد مستخدم مسبقاً.');
    if (result === 'CONFIRM_EMAIL') return setError('تم إنشاء الحساب. تحقق من بريدك الإلكتروني ثم سجّل الدخول.');
    setLocation('/matches');
  };
  return <div className="auth-page"><div className="auth-card"><span className="auth-mark">{isLogin ? <LogIn className="h-7 w-7" /> : <UserPlus className="h-7 w-7" />}</span><h1>{isLogin ? 'تسجيل الدخول' : 'إنشاء حساب جديد'}</h1><p>{isLogin ? 'تابع مبارياتك وأدر رصيدك بأمان.' : 'انضم إلى مجتمع لاعبي eFootball في المغرب.'}</p>{error && <Notice type="error">{error}</Notice>}<form onSubmit={submit} className="form-stack">{isLogin ? <><Field label="اسم المستخدم أو البريد الإلكتروني" value={form.login} onChange={value => update('login', value)} test="input-login" /><Field label="كلمة المرور" type="password" value={form.password} onChange={value => update('password', value)} test="input-password" /></> : <><div className="form-grid"><Field label="اسم المستخدم" value={form.username} onChange={value => update('username', value)} test="input-username" /><Field label="معرّف eFootball" value={form.efootball_id} onChange={value => update('efootball_id', value)} test="input-efootball-id" /></div><Field label="رقم واتساب" value={form.whatsapp} onChange={value => update('whatsapp', value)} test="input-whatsapp" /><Field label="البريد الإلكتروني" type="email" value={form.email} onChange={value => update('email', value)} test="input-email" /><Field label="كلمة المرور" type="password" value={form.password} onChange={value => update('password', value)} test="input-register-password" /></>}<button className="primary-button full" data-testid={`button-submit-${mode}`}>{isLogin ? 'دخول إلى الحساب' : 'إنشاء الحساب'}<ArrowLeft className="h-4 w-4" /></button></form><div className="auth-switch">{isLogin ? <>ليس لديك حساب؟ <Link href="/register">أنشئ حساباً مجاناً</Link></> : <>لديك حساب بالفعل؟ <Link href="/login">سجّل الدخول</Link></>}</div></div></div>;
}

  function RechargeModal({ onClose }: { onClose: () => void }) {
   const { user, recharge, settings, recharges } = useArena(); const [amount, setAmount] = useState('50'); const [method, setMethod] = useState('التحويل البنكي'); const [whatsapp, setWhatsapp] = useState(user?.whatsapp || ''); const [notes, setNotes] = useState(''); const [sent, setSent] = useState(false); const [error, setError] = useState(''); const quickAmounts = (settings.recharge_amounts || '20,50,100,200,500').split(',').map(item => Number(item.trim())).filter(item => item > 0);
   const submit = async (event: FormEvent) => { event.preventDefault(); const value = Number(amount); if (!value || value < 10) return setError('الحد الأدنى للشحن هو 10 دولارات.'); if (await recharge(value, method, whatsapp, notes)) setSent(true); else setError('تعذر حفظ طلب الشحن. حاول مرة أخرى.'); };
    return <Modal onClose={onClose} wide><div className="modal-heading"><span className="panel-icon green"><Wallet className="h-5 w-5" /></span><span><h2>شحن الرصيد</h2><p>أرسل طلب الشحن وستراجعه الإدارة يدوياً.</p></span></div>{sent ? <div className="success-panel"><CheckCircle2 className="h-12 w-12" /><h3>تم إرسال الطلب</h3><p>سيظهر طلبك في سجل الشحن، وستتم إضافة الرصيد بعد المراجعة.</p><button className="primary-button" onClick={onClose}>حسناً</button></div> : <form className="modal-body form-stack" onSubmit={submit}>{error && <Notice type="error">{error}</Notice>}<div className="payment-card"><p>بيانات التحويل</p><strong>{method === 'التحويل البنكي' ? settings.cih_name : settings.cashplus_name}</strong><span>{method === 'التحويل البنكي' ? settings.cih_rib : `Cash Plus • ${settings.cashplus_cin}`}</span></div><div className="quick-amounts"><span>اختر مبلغاً سريعاً</span><div>{quickAmounts.map(value => <button type="button" className={Number(amount) === value ? 'quick-amount active' : 'quick-amount'} onClick={() => setAmount(String(value))} key={value}>{money(value)}</button>)}</div></div><div className="form-grid"><Field label="المبلغ المطلوب ($)" type="number" value={amount} onChange={setAmount} test="input-recharge-amount" /><label className="form-field"><span>طريقة الدفع</span><select value={method} onChange={event => setMethod(event.target.value)}><option>التحويل البنكي</option><option>Cash Plus</option></select></label></div><Field label="رقم واتساب للتأكيد" value={whatsapp} onChange={setWhatsapp} test="input-recharge-whatsapp" /><label className="form-field"><span>ملاحظات إضافية</span><textarea value={notes} onChange={event => setNotes(event.target.value)} rows={3} /></label><button className="primary-button full">إرسال طلب الشحن <ArrowLeft className="h-4 w-4" /></button></form>}<div className="modal-history"><strong>آخر طلباتك</strong>{recharges.filter(item => item.userId === user?.id).slice(0, 3).map(item => <div key={item.id}><span>#{item.id} • {money(item.amount)}</span><StatusBadge status={item.status} /></div>)}</div></Modal>;
}

 function WithdrawModal({ onClose }: { onClose: () => void }) {
  const { user, requestWithdrawal, withdrawals } = useArena(); const [amount, setAmount] = useState(''); const [method, setMethod] = useState('التحويل البنكي'); const [destination, setDestination] = useState(''); const [notes, setNotes] = useState(''); const [error, setError] = useState(''); const [sent, setSent] = useState(false);
  const submit = async (event: FormEvent) => { event.preventDefault(); const okay = await requestWithdrawal(Number(amount), method, destination, notes); if (!okay) return setError('تعذر تسجيل طلب السحب. تحقق من المبلغ والرصيد ثم حاول مرة أخرى.'); setSent(true); };
   return <Modal onClose={onClose}><div className="modal-heading"><span className="panel-icon amber"><ArrowUpFromLine className="h-5 w-5" /></span><span><h2>طلب سحب</h2><p>الرصيد المتاح: <b>{money(user?.balance || 0)}</b></p></span></div>{sent ? <div className="success-panel"><CheckCircle2 className="h-12 w-12" /><h3>تم تسجيل طلب السحب</h3><p>سيتم تحويل المبلغ بعد اعتماد الإدارة.</p><button className="primary-button" onClick={onClose}>حسناً</button></div> : <form className="modal-body form-stack" onSubmit={submit}>{error && <Notice type="error">{error}</Notice>}<Field label="المبلغ ($)" type="number" value={amount} onChange={setAmount} test="input-withdraw-amount" /><label className="form-field"><span>طريقة الاستلام</span><select value={method} onChange={event => setMethod(event.target.value)}><option>التحويل البنكي</option><option>Cash Plus</option></select></label><Field label="رقم الحساب أو الهاتف" value={destination} onChange={setDestination} test="input-withdraw-destination" /><label className="form-field"><span>ملاحظات</span><textarea value={notes} onChange={event => setNotes(event.target.value)} rows={2} /></label><button className="primary-button full">إرسال طلب السحب</button></form>}<div className="modal-history"><strong>آخر طلبات السحب</strong>{withdrawals.filter(item => item.userId === user?.id).slice(0, 3).map(item => <div key={item.id}><span>#{item.id} • {money(item.amount)}</span><StatusBadge status={item.status} /></div>)}</div></Modal>;
}

function CreateMatchModal({ onClose }: { onClose: () => void }) {
  const { user, createMatch } = useArena(); const [, setLocation] = useLocation(); const [title, setTitle] = useState(''); const [stake, setStake] = useState('20'); const [platform, setPlatform] = useState('الهاتف'); const [error, setError] = useState('');
   const submit = (event: FormEvent) => { event.preventDefault(); const value = Number(stake); const id = value >= 5 ? createMatch(title, value, platform) : null; if (!id) return setError(value < 5 ? 'الحد الأدنى للمباراة هو 5 دولارات.' : 'رصيدك غير كافٍ لإنشاء هذه المباراة.'); onClose(); setLocation(`/matches/${id}`); };
   return <Modal onClose={onClose}><div className="modal-heading"><span className="panel-icon green"><Swords className="h-5 w-5" /></span><span><h2>إنشاء مباراة جديدة</h2><p>حدّد قيمة الرهان والمنصة ثم انتظر منافساً.</p></span></div><form className="modal-body form-stack" onSubmit={submit}>{error && <Notice type="error">{error}</Notice>}<Field label="عنوان المباراة" value={title} onChange={setTitle} placeholder="مثال: تحدٍّ سريع" /><div className="form-grid"><Field label="قيمة الرهان ($)" type="number" value={stake} onChange={setStake} /><label className="form-field"><span>المنصة</span><select value={platform} onChange={event => setPlatform(event.target.value)}><option>الهاتف</option><option>PlayStation</option><option>Xbox / PC</option></select></label></div><div className="summary-row"><span>الجائزة المتوقعة</span><strong>{money(Number(stake || 0) * 1.8)}</strong></div><button className="primary-button full">نشر التحدي <ArrowLeft className="h-4 w-4" /></button></form></Modal>;
}

function HomePage() {
  const { user, matches, tournaments } = useArena(); const [, setLocation] = useLocation(); const [createOpen, setCreateOpen] = useState(false); const [rechargeOpen, setRechargeOpen] = useState(false);
  useEffect(() => { const prize = document.querySelector('.featured-prize strong'); if (prize) prize.textContent = money(180); }, []);
  const enter = (kind: 'match' | 'recharge') => { if (!user) return setLocation('/login'); kind === 'match' ? setCreateOpen(true) : setRechargeOpen(true); };
  return <div className="home-page"><section className="hero-section"><div className="hero-glow" /><div className="shell hero-grid"><div className="hero-copy"><span className="eyebrow"><span className="pulse-dot" />منصة تنافسية موثوقة</span><h1>نافس بقوة.<br /><em>اربح بعدل.</em></h1><p>خض مباريات eFootball وبطولاته مع لاعبين من المغرب، مع محفظة آمنة ونظام ضمان يحمي حقوقك في كل مواجهة.</p><div className="hero-actions"><button className="primary-button large" onClick={() => enter('match')}>إنشاء تحدٍّ جديد <Swords className="h-5 w-5" /></button><button className="secondary-button large" onClick={() => enter('recharge')}>شحن المحفظة <Wallet className="h-5 w-5" /></button></div><div className="hero-stats"><div><strong>1,240+</strong><span>لاعب نشط</span></div><div><strong>{matches.filter(item => item.status === 'OPEN').length + 12}</strong><span>مباراة مفتوحة</span></div><div><strong>{tournaments.length + 8}</strong><span>بطولات ناجحة</span></div></div></div><div className="hero-card"><div className="hero-card-top"><span className="live-dot" />مباريات مباشرة الآن <Sparkles className="h-4 w-4 text-amber-300" /></div><div className="featured-match"><span className="match-kicker">مواجهة الليلة</span><h3>قمة الأبطال</h3><div className="versus"><span><b>YA</b>Yassine_7</span><strong>VS</strong><span>SaraBall<b>SA</b></span></div><div className="featured-prize"><span>الجائزة المضمونة</span><strong>180 د.م.</strong></div></div><div className="hero-card-footer"><span><ShieldCheck className="h-4 w-4 text-emerald-400" /> ضمان مالي مفعّل</span><span>10 دقائق</span></div></div></div></section><section className="shell feature-section"><div className="section-heading"><div><span className="eyebrow muted">ابدأ بخطوة واحدة</span><h2>كل ما تحتاجه للمنافسة</h2></div><Link href="/matches" className="text-link">استكشف المباريات <ArrowLeft className="h-4 w-4" /></Link></div><div className="feature-grid"><Feature icon={Wallet} title="محفظة آمنة" text="اشحن واسحب رصيدك بوضوح، وكل طلب يخضع للمراجعة والتتبع." tone="green" /><Feature icon={Swords} title="مواجهات عادلة" text="أنشئ تحدياً أو انضم إلى مباراة مفتوحة واختر منصتك المفضلة." tone="blue" /><Feature icon={Trophy} title="بطولات حقيقية" text="نافس في بطولات منظمة بجوائز واضحة وقواعد معلنة." tone="amber" /></div></section>{createOpen && <CreateMatchModal onClose={() => setCreateOpen(false)} />}{rechargeOpen && <RechargeModal onClose={() => setRechargeOpen(false)} />}</div>;
}
function Feature({ icon: Icon, title, text, tone }: { icon: typeof Wallet; title: string; text: string; tone: string }) { return <div className="feature-card"><span className={`panel-icon ${tone}`}><Icon className="h-5 w-5" /></span><h3>{title}</h3><p>{text}</p><ArrowLeft className="feature-arrow h-4 w-4" /></div>; }

function MatchesPage() {
  const { matches, user, joinMatch } = useArena(); const [, setLocation] = useLocation(); const [status, setStatus] = useState('OPEN'); const [platform, setPlatform] = useState('الكل'); const [search, setSearch] = useState(''); const [createOpen, setCreateOpen] = useState(false); const [rechargeOpen, setRechargeOpen] = useState(false);
  const filtered = matches.filter(item => (status === 'ALL' || item.status === status) && (platform === 'الكل' || item.platform === platform) && (!search || `${item.title} ${item.creator_name}`.toLowerCase().includes(search.toLowerCase())));
  const join = (match: Match) => { if (!user) return setLocation('/login'); if (user.balance < match.stake) return setRechargeOpen(true); if (joinMatch(match.id)) setLocation(`/matches/${match.id}`); };
  return <div className="shell page-wrap"><div className="page-header"><PageTitle icon={Swords} title="المباريات المفتوحة" subtitle="اختر تحدياً مناسباً أو أنشئ مباراة جديدة." /><button className="primary-button" onClick={() => user ? setCreateOpen(true) : setLocation('/login')}><Plus className="h-4 w-4" />إنشاء مباراة</button></div><div className="toolbar"><div className="filter-list">{[['OPEN', 'متاحة'], ['PLAYING', 'جارية'], ['DISPUTE', 'نزاعات'], ['ALL', 'الكل']].map(([id, label]) => <button key={id} onClick={() => setStatus(id)} className={status === id ? 'filter-active' : ''}>{label}</button>)}</div><div className="toolbar-fields"><div className="search-box"><Search className="h-4 w-4" /><input value={search} onChange={event => setSearch(event.target.value)} placeholder="ابحث باسم اللاعب أو المباراة" /></div><select value={platform} onChange={event => setPlatform(event.target.value)}><option>الكل</option><option>الهاتف</option><option>PlayStation</option><option>Xbox / PC</option></select></div></div>{filtered.length === 0 ? <Empty icon={Swords} text="لا توجد مباريات مطابقة للبحث حالياً." /> : <div className="match-grid">{filtered.map(match => <MatchCard key={match.id} match={match} user={user} onJoin={() => join(match)} onOpen={() => setLocation(`/matches/${match.id}`)} />)}</div>}{createOpen && <CreateMatchModal onClose={() => setCreateOpen(false)} />}{rechargeOpen && <RechargeModal onClose={() => setRechargeOpen(false)} />}</div>;
}
function MatchCard({ match, user, onJoin, onOpen }: { match: Match; user: User | null; onJoin: () => void; onOpen: () => void }) { const owner = user?.id === match.creator_id; return <article className="match-card"><div className="match-card-head"><span><Gamepad2 className="h-4 w-4" />{match.platform}</span><StatusBadge status={match.status === 'OPEN' ? 'OPEN_MATCH' : match.status} /></div><h3>{match.title}</h3><div className="players-line"><div><b>{initials(match.creator_name)}</b><span>{match.creator_name}<small>{match.creator_efootball_id}</small></span></div><strong>VS</strong><div className="opponent"><b>{match.opponent_name ? initials(match.opponent_name) : '?'}</b><span>{match.opponent_name || 'بانتظار منافس'}<small>{match.opponent_efootball_id || 'سيظهر بعد الانضمام'}</small></span></div></div><div className="card-metrics"><span>قيمة الرهان<strong>{money(match.stake)}</strong></span><span>الجائزة<strong className="amber-text">{money(match.prize)}</strong></span></div><button className={owner || match.status !== 'OPEN' ? 'secondary-button full' : 'primary-button full'} onClick={owner || match.status !== 'OPEN' ? onOpen : onJoin}>{owner ? 'إدارة المباراة' : match.status === 'OPEN' ? 'قبول التحدي' : 'عرض التفاصيل'}<ArrowLeft className="h-4 w-4" /></button></article>; }

function MatchDetailPage() {
  const [evidenceFiles, setEvidenceFiles] = useState<File[]>([]);
  const { id } = useParams<{ id: string }>(); const { matches, user, updateMatch, addMessage, openDispute, joinMatch } = useArena(); const [, setLocation] = useLocation(); const match = matches.find(item => item.id === id); const [chat, setChat] = useState(''); const [code, setCode] = useState(match?.room_code || ''); const [disputeOpen, setDisputeOpen] = useState(false); const [subject, setSubject] = useState(''); const [details, setDetails] = useState(''); const [message, setMessage] = useState('');
  if (!match) return <div className="shell page-wrap"><Empty text="المباراة غير موجودة." /><Link href="/matches" className="back-link"><ArrowRight className="h-4 w-4" />العودة إلى المباريات</Link></div>;
  const participant = !!user && (user.id === match.creator_id || user.id === match.opponent_id); const submitChat = (event: FormEvent) => { event.preventDefault(); addMessage(match.id, chat); setChat(''); }; const submitDispute = (event: FormEvent) => { event.preventDefault(); openDispute(match.id, subject, details, evidenceFiles); setEvidenceFiles([]); setDisputeOpen(false); setMessage('تم فتح النزاع وسيظهر في لوحة الإدارة.'); };
  return <div className="shell page-wrap"><Link href="/matches" className="back-link"><ArrowRight className="h-4 w-4" />العودة إلى المباريات</Link>{message && <Notice>{message}</Notice>}<div className="detail-card"><div className="detail-head"><span className="mono">#{match.id} • {match.platform}</span><StatusBadge status={match.status} /></div><div className="detail-versus"><div className="detail-player"><b>{initials(match.creator_name)}</b><strong>{match.creator_name}</strong><small>{match.creator_efootball_id}</small></div><div className="detail-prize"><span>الجائزة</span><strong>{money(match.prize)}</strong><small>الرهان: {money(match.stake)} لكل لاعب</small></div><div className="detail-player"><b>{initials(match.opponent_name || '؟')}</b><strong>{match.opponent_name || 'بانتظار منافس'}</strong><small>{match.opponent_efootball_id || 'لم ينضم بعد'}</small></div></div>{match.status === 'OPEN' && user && user.id !== match.creator_id && <button className="primary-button" onClick={() => joinMatch(match.id) && setMessage('تم الانضمام إلى المباراة بنجاح.')}>قبول التحدي</button>}{participant && <div className="room-code"><span>رمز الغرفة</span><strong>{code || 'لم يحدده المضيف بعد'}</strong><button onClick={() => navigator.clipboard?.writeText(code)} aria-label="نسخ"><Copy className="h-4 w-4" /></button>{user.id === match.creator_id && <div className="inline-edit"><input value={code} onChange={event => setCode(event.target.value)} placeholder="أدخل رمز الغرفة" /><button onClick={() => updateMatch(match.id, { room_code: code })}><Save className="h-4 w-4" />حفظ</button></div>}</div>}<div className="detail-columns"><div className="chat-panel"><div className="panel-heading"><span><MessageCircle className="h-4 w-4" />محادثة المباراة</span><small>{match.messages.length} رسائل</small></div><div className="chat-messages">{match.messages.length ? match.messages.map(item => <div className={item.user_id === user?.id ? 'chat-message own' : 'chat-message'} key={item.id}><b>{item.username}</b><p>{item.message}</p></div>) : <Empty icon={MessageCircle} text="لا توجد رسائل بعد." />}</div>{participant && <form className="chat-form" onSubmit={submitChat}><input value={chat} onChange={event => setChat(event.target.value)} placeholder="اكتب رسالة للمنافس" /><button aria-label="إرسال"><ArrowLeft className="h-4 w-4" /></button></form>}</div><div className="detail-actions"><h3>إجراءات المباراة</h3><p>احتفظ بإثبات النتيجة والتواصل داخل المنصة لحماية حقوقك.</p>{participant && <button className="danger-button full" onClick={() => setDisputeOpen(true)}><AlertTriangle className="h-4 w-4" />فتح نزاع</button>}</div></div></div>{disputeOpen && <Modal onClose={() => setDisputeOpen(false)}><div className="modal-heading"><span className="panel-icon red"><AlertTriangle className="h-5 w-5" /></span><span><h2>فتح نزاع</h2><p>صف المشكلة بدقة وأرفق التفاصيل اللازمة للإدارة.</p></span></div><form className="modal-body form-stack" onSubmit={submitDispute}><Field label="عنوان النزاع" value={subject} onChange={setSubject} placeholder="مثال: لم يرسل المنافس النتيجة" /><label className="form-field"><span>التفاصيل</span><textarea rows={5} value={details} onChange={event => setDetails(event.target.value)} required /></label><label className="form-field"><span>الأدلة (صور أو فيديو)</span><input type="file" accept="image/*,video/*" multiple onChange={event => setEvidenceFiles(Array.from(event.target.files || []))} /><small>{evidenceFiles.length ? `تم اختيار ${evidenceFiles.length} ملف` : 'يمكنك اختيار أكثر من ملف'}</small></label><button className="danger-button full">إرسال النزاع</button></form></Modal>}</div>;
}

function MatchDetailPageV2() {
  const [evidenceFiles, setEvidenceFiles] = useState<File[]>([]); const { id } = useParams<{ id: string }>(); const { matches, user, updateMatch, addMessage, openDispute, joinMatch, submitMatchResultClaim } = useArena(); const [, setLocation] = useLocation(); const match = matches.find(item => item.id === id); const [chat, setChat] = useState(''); const [code, setCode] = useState(match?.room_code || ''); const [disputeOpen, setDisputeOpen] = useState(false); const [subject, setSubject] = useState(''); const [details, setDetails] = useState(''); const [message, setMessage] = useState('');
  if (!match) return <div className="shell page-wrap"><Empty text="المباراة غير موجودة." /><Link href="/matches" className="back-link"><ArrowRight className="h-4 w-4" />العودة إلى المباريات</Link></div>;
  const participant = !!user && (user.id === match.creator_id || user.id === match.opponent_id); const canClaim = participant && !!match.opponent_id && ['PLAYING', 'COMPLETED', 'DISPUTE'].includes(match.status) && match.payout_status !== 'APPROVED'; const ownClaim = user?.id === match.creator_id ? match.creator_claim : match.opponent_claim; const rivalClaim = user?.id === match.creator_id ? match.opponent_claim : match.creator_claim; const claimText = (winnerId?: string) => winnerId ? winnerId === user?.id ? 'أنا ربحت' : 'الخصم ربح' : 'لم يرسل بعد';
  const submitChat = (event: FormEvent) => { event.preventDefault(); if (!chat.trim()) return; addMessage(match.id, chat); setChat(''); };
  const submitClaim = async (winnerId: string) => { const ok = await submitMatchResultClaim(match.id, winnerId); setMessage(ok ? 'تم إرسال تصريحك بالنتيجة. ستراجع الإدارة تصريحات اللاعبين قبل صرف الجائزة.' : 'تعذر إرسال التصريح. تأكد أن المباراة ما زالت قيد المراجعة.'); };
  const submitDispute = (event: FormEvent) => { event.preventDefault(); openDispute(match.id, subject, details, evidenceFiles); setEvidenceFiles([]); setDisputeOpen(false); setMessage('تم فتح النزاع وسيظهر في لوحة الإدارة.'); };
  return <div className="shell page-wrap"><Link href="/matches" className="back-link"><ArrowRight className="h-4 w-4" />العودة إلى المباريات</Link>{message && <Notice>{message}</Notice>}<div className="detail-card"><div className="detail-head"><span className="mono">#{match.id} • {match.platform}</span><StatusBadge status={match.status} /></div><div className="detail-versus"><div className="detail-player"><b>{initials(match.creator_name)}</b><strong>{match.creator_name}</strong><small>{match.creator_efootball_id}</small></div><div className="detail-prize"><span>الجائزة</span><strong>{money(match.prize)}</strong><small>الرهان: {money(match.stake)} لكل لاعب</small></div><div className="detail-player"><b>{initials(match.opponent_name || '؟')}</b><strong>{match.opponent_name || 'بانتظار منافس'}</strong><small>{match.opponent_efootball_id || 'لم ينضم بعد'}</small></div></div>{match.status === 'OPEN' && user && user.id !== match.creator_id && <button className="primary-button" onClick={() => joinMatch(match.id) && setMessage('تم الانضمام إلى المباراة بنجاح.')}>قبول التحدي</button>}{participant && <div className="room-code"><span>رمز الغرفة</span><strong>{code || 'لم يحدده المضيف بعد'}</strong><button onClick={() => navigator.clipboard?.writeText(code)} aria-label="نسخ"><Copy className="h-4 w-4" /></button>{user && user.id === match.creator_id && <div className="inline-edit"><input value={code} onChange={event => setCode(event.target.value)} placeholder="أدخل رمز الغرفة" /><button onClick={() => updateMatch(match.id, { room_code: code })}><Save className="h-4 w-4" />حفظ</button></div>}</div>}{canClaim && user && <div className="result-claim-panel"><div className="panel-heading"><span><CheckCircle2 className="h-4 w-4" />تصريح نتيجة المباراة</span><small>اختر بعد انتهاء المواجهة</small></div><p>اختر النتيجة التي تؤكدها. ستظهر تصريحات الطرفين للإدارة قبل اعتماد الجائزة.</p><div className="claim-actions"><button className="primary-button" onClick={() => submitClaim(user.id)}>أنا ربحت</button><button className="secondary-button" onClick={() => submitClaim(user.id === match.creator_id ? match.opponent_id! : match.creator_id)}>الخصم ربح</button></div><div className="claim-summary"><span><small>تصريحك</small><b>{claimText(ownClaim)}</b></span><span><small>تصريح الخصم</small><b>{claimText(rivalClaim)}</b></span></div></div>}<div className="detail-columns"><div className="chat-panel"><div className="panel-heading"><span><MessageCircle className="h-4 w-4" />محادثة المباراة</span><small>{match.messages.length} رسائل</small></div><div className="chat-messages">{match.messages.length ? match.messages.map(item => <div className={item.user_id === user?.id ? 'chat-message own' : 'chat-message'} key={item.id}><b>{item.username}</b><span>{item.message}</span></div>) : <Empty icon={MessageCircle} text="لا توجد رسائل بعد." />}</div>{participant && <form className="chat-form" onSubmit={submitChat}><input value={chat} onChange={event => setChat(event.target.value)} placeholder="اكتب رسالة للمنافس" /><button className="primary-button small" aria-label="إرسال"><ArrowLeft className="h-4 w-4" /></button></form>}</div><aside className="detail-side"><div className="panel-heading"><span><ShieldCheck className="h-4 w-4" />حماية المباراة</span></div><p>لا يتم صرف الجائزة إلا بعد مراجعة النتيجة من الإدارة.</p>{participant && <button className="danger-button full" onClick={() => setDisputeOpen(true)}><AlertTriangle className="h-4 w-4" />فتح نزاع</button>}</aside></div></div>{disputeOpen && <Modal onClose={() => setDisputeOpen(false)} wide><div className="modal-heading"><span className="panel-icon red"><AlertTriangle className="h-5 w-5" /></span><span><h2>فتح نزاع على المباراة</h2><p>أرسل تفاصيل واضحة وأرفق الأدلة إن وجدت.</p></span></div><form className="modal-body form-stack" onSubmit={submitDispute}><Field label="موضوع النزاع" value={subject} onChange={setSubject} placeholder="مثال: النتيجة غير صحيحة" /><label className="form-field"><span>التفاصيل</span><textarea value={details} onChange={event => setDetails(event.target.value)} rows={5} required /></label><label className="form-field"><span>الأدلة</span><input type="file" multiple onChange={event => setEvidenceFiles(Array.from(event.target.files || []))} /></label><button className="primary-button full">إرسال النزاع</button></form></Modal>}</div>;
}

function TournamentsPage() {
  const { tournaments, user, joinTournament } = useArena(); const [, setLocation] = useLocation(); const [message, setMessage] = useState(''); const [rechargeOpen, setRechargeOpen] = useState(false);
  const join = (item: Tournament) => { if (!user) return setLocation('/login'); if (user.balance < item.entry_fee) return setRechargeOpen(true); setMessage(joinTournament(item.id) ? 'تم تسجيلك في البطولة بنجاح.' : 'تعذّر التسجيل في هذه البطولة.'); };
  return <div className="shell page-wrap"><PageTitle icon={Trophy} tone="amber" title="البطولات الرسمية" subtitle="بطولات منظمة بجوائز معلنة وقواعد واضحة." />{message && <Notice>{message}</Notice>}<div className="tournament-grid">{tournaments.map(item => <article className={`tournament-card ${item.featured ? 'is-featured' : ''}`} key={item.id}><div className="tournament-cover">{item.image_url ? <img src={item.image_url} alt={item.title} /> : <Trophy className="h-16 w-16" />}<div className="tournament-cover-overlay" /><span>الجائزة {money(item.prize_pool)}</span><StatusBadge status={item.status || 'UPCOMING'} /></div><div className="tournament-body"><div className="split-row"><h2>{item.title}</h2><span className="capacity">{item.participant_count}/{item.max_players}</span></div><p>{item.description || item.rules}</p><div className="tournament-meta"><span>رسوم التسجيل<strong>{money(item.entry_fee)}</strong></span><span>موعد الانطلاق<strong>{item.start_date || 'سيحدد لاحقاً'}</strong></span><span>المنصة<strong>{item.platform || 'الهاتف'}</strong></span><span>القواعد<strong>{item.rules}</strong></span></div><button className={item.joined ? 'secondary-button full' : 'primary-button full'} disabled={item.joined || item.status === 'CANCELLED' || item.status === 'COMPLETED'} onClick={() => join(item)}>{item.joined ? 'تم التسجيل' : item.status === 'COMPLETED' ? 'انتهت البطولة' : item.status === 'CANCELLED' ? 'البطولة ملغاة' : 'التسجيل في البطولة'}<ArrowLeft className="h-4 w-4" /></button></div></article>)}</div>{rechargeOpen && <RechargeModal onClose={() => setRechargeOpen(false)} />}</div>;
}
function LeaderboardPage() { const { players } = useArena(); return <div className="shell page-wrap"><PageTitle icon={BarChart3} tone="amber" title="لوحة الصدارة" subtitle="أفضل اللاعبين حسب عدد الانتصارات ونسبة الفوز." /><div className="table-card"><table><thead><tr><th>الترتيب</th><th>اللاعب</th><th>المعرّف</th><th>الانتصارات</th><th>الخسائر</th><th>نسبة الفوز</th></tr></thead><tbody>{players.map((player, index) => <tr key={player.id}><td><span className={`rank rank-${index + 1}`}>{index + 1}</span></td><td><span className="table-player"><b>{initials(player.username)}</b>{player.username}</span></td><td className="mono">{player.efootball_id}</td><td className="green-text mono">{player.wins}</td><td className="red-text mono">{player.losses}</td><td className="mono">{player.win_rate}%</td></tr>)}</tbody></table></div></div>; }

function ProfilePage() {
  const { user, transactions, withdrawals } = useArena(); const [rechargeOpen, setRechargeOpen] = useState(false); const [withdrawOpen, setWithdrawOpen] = useState(false);
  if (!user) return <div className="shell page-wrap"><Empty icon={UserIcon} text="سجّل الدخول لعرض ملفك الشخصي." /><Link href="/login" className="primary-button">تسجيل الدخول</Link></div>;
  return <div className="shell page-wrap"><div className="profile-grid"><section className="profile-card"><div className="profile-head"><span className="avatar large">{initials(user.username)}</span><span><h1>{user.username}</h1><p>{user.email}</p><StatusBadge status={user.role === 'ADMIN' ? 'APPROVED' : 'OPEN_MATCH'} /></span></div><div className="profile-details"><span><small>معرّف eFootball</small><strong className="mono">{user.efootball_id}</strong></span><span><small>رقم واتساب</small><strong className="mono">{user.whatsapp || 'غير مضاف'}</strong></span><span><small>النتائج</small><strong><i className="green-text">{user.wins} فوز</i> / <i className="red-text">{user.losses} خسارة</i></strong></span></div></section><section className="wallet-card"><div className="split-row"><span className="wallet-label"><Wallet className="h-4 w-4" />المحفظة</span><span className="active-label">نشطة</span></div><small>الرصيد المتاح</small><strong className="wallet-amount">{money(user.balance)}</strong><div className="wallet-actions"><button className="primary-button" onClick={() => setRechargeOpen(true)}><ArrowDownToLine className="h-4 w-4" />شحن</button><button className="secondary-button" onClick={() => setWithdrawOpen(true)}><ArrowUpFromLine className="h-4 w-4" />سحب</button></div></section></div><div className="profile-lower"><section className="panel-card"><div className="panel-heading"><span><Activity className="h-4 w-4" />سجل المعاملات</span><Link href="/profile" className="text-link">عرض الكل</Link></div>{transactions.length ? <div className="transaction-list">{transactions.slice(0, 8).map(item => <div className="transaction-row" key={item.id}><span className={`transaction-icon ${item.amount > 0 ? 'green' : 'blue'}`}>{item.amount > 0 ? <ArrowDownToLine className="h-4 w-4" /> : <ArrowUpFromLine className="h-4 w-4" />}</span><span><strong>{item.description}</strong><small>{date(item.created_at)}</small></span><b className={item.amount > 0 ? 'green-text' : 'red-text'}>{item.amount > 0 ? '+' : ''}{money(item.amount)}</b></div>)}</div> : <Empty icon={Clock3} text="لا توجد معاملات بعد." />}</section><section className="panel-card"><div className="panel-heading"><span><ArrowUpFromLine className="h-4 w-4" />طلبات السحب</span></div>{withdrawals.filter(item => item.userId === user.id).length ? withdrawals.filter(item => item.userId === user.id).slice(0, 6).map(item => <div className="compact-row" key={item.id}><span><strong>#{item.id}</strong><small>{date(item.created_at)}</small></span><span><b>{money(item.amount)}</b><StatusBadge status={item.status} /></span></div>) : <Empty icon={ArrowUpFromLine} text="لم ترسل أي طلب سحب." />}</section></div>{rechargeOpen && <RechargeModal onClose={() => setRechargeOpen(false)} />}{withdrawOpen && <WithdrawModal onClose={() => setWithdrawOpen(false)} />}</div>;
}

function AdminPage() {
  const { user } = useArena(); const { section } = useParams<{ section?: string }>();
  if (!user || user.role !== 'ADMIN') return <div className="shell page-wrap"><div className="access-denied"><ShieldAlert className="h-12 w-12" /><h1>الوصول مخصص للإدارة</h1><p>يجب تسجيل الدخول بحساب إداري لعرض هذه الصفحة.</p><Link href="/login" className="primary-button">تسجيل الدخول</Link></div></div>;
  return <AdminLayout section={section || 'overview'} />;
}
const adminLinks = [
  { id: 'overview', label: 'نظرة عامة', icon: LayoutDashboard },
  { id: 'matches', label: 'مراقبة المباريات', icon: Monitor },
  { id: 'tournaments', label: 'إدارة البطولات', icon: Trophy },
  { id: 'activity', label: 'سجل النشاطات', icon: Activity },
  { id: 'recharges', label: 'طلبات الشحن', icon: ArrowDownToLine },
  { id: 'withdrawals', label: 'طلبات السحب', icon: ArrowUpFromLine },
  { id: 'disputes', label: 'النزاعات', icon: AlertTriangle },
  { id: 'users', label: 'المستخدمون', icon: Users },
  { id: 'settings', label: 'إعدادات المنصة', icon: Settings },
];
function AdminLayout({ section }: { section: string }) {
  const { matches, tournaments, saveTournament, deleteTournament, recharges, withdrawals, disputes } = useArena(); const pendingMatchReview = matches.filter(item => item.opponent_id && item.status !== 'OPEN' && item.status !== 'CANCELLED' && item.payout_status !== 'APPROVED').length; const pendingRecharge = recharges.filter(item => item.status === 'PENDING').length; const pendingWithdrawal = withdrawals.filter(item => item.status === 'PENDING').length; const openDisputes = disputes.filter(item => item.status === 'OPEN' || item.status === 'UNDER_REVIEW').length; const current = adminLinks.find(item => item.id === section)?.label || 'نظرة عامة';
   const content = section === 'matches' ? <AdminMatchesPage /> : section === 'tournaments' ? <AdminTournamentsPageV2 tournaments={tournaments} saveTournament={saveTournament} deleteTournament={deleteTournament} /> : section === 'activity' ? <AdminActivityPage /> : section === 'recharges' ? <AdminRechargesPage /> : section === 'withdrawals' ? <AdminWithdrawalsPage /> : section === 'disputes' ? <AdminDisputesPage /> : section === 'users' ? <AdminUsersDetailsPage /> : section === 'settings' ? <AdminSettingsPage /> : <AdminOverview />;
  return <div className="admin-shell shell"><aside className="admin-sidebar"><div className="admin-brand"><span className="brand-mark"><ShieldCheck className="h-5 w-5" /></span><span><strong>مركز الإدارة</strong><small>eFootball ARENA</small></span></div><nav>{adminLinks.map(item => { const Icon = item.icon; const count = item.id === 'matches' ? pendingMatchReview : item.id === 'recharges' ? pendingRecharge : item.id === 'withdrawals' ? pendingWithdrawal : item.id === 'disputes' ? openDisputes : 0; return <Link href={`/admin/${item.id}`} key={item.id} className={section === item.id || (!section && item.id === 'overview') ? 'admin-link active' : 'admin-link'}><Icon className="h-4 w-4" />{item.label}{count > 0 && <span className="nav-count">{count}</span>}</Link>; })}</nav><Link href="/" className="back-site"><ArrowRight className="h-4 w-4" />العودة إلى الموقع</Link></aside><main className="admin-content"><div className="admin-topbar"><div><span className="admin-kicker">لوحة الإدارة / {current}</span><h1>{current}</h1></div><span className="admin-session"><span className="online-dot" />مسجّل باسم المدير</span></div>{content}</main></div>;
}
function AdminStat({ icon: Icon, label, value, detail, tone = 'green' }: { icon: typeof Wallet; label: string; value: string; detail?: string; tone?: string }) { return <div className="admin-stat"><span className={`stat-icon ${tone}`}><Icon className="h-5 w-5" /></span><span><small>{label}</small><strong>{value}</strong>{detail && <em>{detail}</em>}</span></div>; }
function AdminOverview() {
  const { users, recharges, withdrawals, disputes, activities, matches, tournaments } = useArena(); const pendingRecharge = recharges.filter(item => item.status === 'PENDING').length; const pendingWithdrawal = withdrawals.filter(item => item.status === 'PENDING').length; const openDisputes = disputes.filter(item => item.status === 'OPEN' || item.status === 'UNDER_REVIEW').length;
  return <div className="admin-page"><div className="admin-welcome"><div><span className="eyebrow">مركز العمليات</span><h2>مرحباً بك في لوحة التحكم</h2><p>تابع كل عمليات الشحن والسحب والنزاعات ونشاطات المستخدمين من مكان واحد.</p></div><Link href="/admin/activity" className="secondary-button"><Activity className="h-4 w-4" />عرض السجل الكامل</Link></div><div className="admin-stats"><AdminStat icon={ArrowDownToLine} label="طلبات الشحن المعلقة" value={String(pendingRecharge)} detail="تحتاج إلى مراجعة" /><AdminStat icon={ArrowUpFromLine} label="طلبات السحب المعلقة" value={String(pendingWithdrawal)} detail="تحتاج إلى تنفيذ" tone="amber" /><AdminStat icon={AlertTriangle} label="النزاعات المفتوحة" value={String(openDisputes)} detail="تحتاج إلى قرار" tone="red" /><AdminStat icon={Users} label="إجمالي المستخدمين" value={String(users.length)} detail={`${matches.length} مباريات • ${tournaments.length} بطولات`} tone="blue" /></div><div className="admin-columns"><section className="panel-card"><div className="panel-heading"><span><Activity className="h-4 w-4" />آخر النشاطات</span><Link href="/admin/activity" className="text-link">السجل الكامل</Link></div><ActivityList items={activities.slice(0, 8)} /></section><section className="panel-card quick-panel"><div className="panel-heading"><span><Zap className="h-4 w-4" />إجراءات سريعة</span></div><QuickAction href="/admin/recharges" icon={ArrowDownToLine} title="مراجعة الشحن" detail={`${pendingRecharge} طلبات معلقة`} tone="green" /><QuickAction href="/admin/withdrawals" icon={ArrowUpFromLine} title="معالجة السحب" detail={`${pendingWithdrawal} طلبات معلقة`} tone="amber" /><QuickAction href="/admin/disputes" icon={AlertTriangle} title="فحص النزاعات" detail={`${openDisputes} نزاعات مفتوحة`} tone="red" /><QuickAction href="/admin/users" icon={Users} title="إدارة المستخدمين" detail="الأرصدة والحسابات" tone="blue" /></section></div></div>;
}
function QuickAction({ href, icon: Icon, title, detail, tone }: { href: string; icon: typeof Wallet; title: string; detail: string; tone: string }) { return <Link href={href} className="quick-action"><span className={`stat-icon ${tone}`}><Icon className="h-4 w-4" /></span><span><strong>{title}</strong><small>{detail}</small></span><ArrowLeft className="h-4 w-4" /></Link>; }
function ActivityList({ items }: { items: ActivityRecord[] }) { return items.length ? <div className="activity-list">{items.map(item => <div className="activity-row" key={item.id}><span className={`activity-icon ${item.category.toLowerCase()}`}><Activity className="h-4 w-4" /></span><span><strong>{item.action}</strong><small>{item.description} • {item.username} • {date(item.created_at)}</small></span>{item.amount !== undefined && <b className="mono">{money(item.amount)}</b>}</div>)}</div> : <Empty text="لا توجد نشاطات مسجلة بعد." />; }

function AdminRechargesPage() {
  const { recharges, approveRecharge } = useArena(); const [filter, setFilter] = useState('PENDING'); const [query, setQuery] = useState(''); const rows = recharges.filter(item => (filter === 'ALL' || item.status === filter) && (!query || `${item.id} ${item.username} ${item.whatsapp}`.toLowerCase().includes(query.toLowerCase())));
  return <div className="admin-page"><AdminSectionHeader icon={ArrowDownToLine} title="طلبات الشحن" subtitle="راجع التحويلات وأضف الرصيد بعد التأكد من البيانات." count={recharges.filter(item => item.status === 'PENDING').length} /><AdminFilters filter={filter} setFilter={setFilter} query={query} setQuery={setQuery} options={['PENDING', 'APPROVED', 'REJECTED', 'ALL']} />{rows.length ? <div className="request-list">{rows.map(item => <article className="request-card" key={item.id}><div className="request-main"><span className="request-icon green"><ArrowDownToLine className="h-5 w-5" /></span><span><strong>{item.username}</strong><small>#{item.id} • {date(item.created_at)}</small></span><span className="request-amount green-text">+{money(item.amount)}</span><StatusBadge status={item.status} /></div><div className="request-details"><span><small>طريقة الدفع</small><b>{item.payment_method}</b></span><span><small>واتساب</small><b className="mono">{item.whatsapp || 'غير متوفر'}</b></span><span><small>ملاحظات</small><b>{item.notes || 'لا توجد ملاحظات'}</b></span></div>{item.status === 'PENDING' && <div className="request-actions"><button className="primary-button small" onClick={() => approveRecharge(item.id, true)}><Check className="h-4 w-4" />اعتماد وإضافة الرصيد</button><button className="danger-button small" onClick={() => approveRecharge(item.id, false)}><XCircle className="h-4 w-4" />رفض الطلب</button></div>}</article>)}</div> : <Empty icon={ArrowDownToLine} text="لا توجد طلبات شحن بهذه الحالة." />}</div>;
}
function AdminWithdrawalsPage() {
  const { withdrawals, approveWithdrawal } = useArena(); const [filter, setFilter] = useState('PENDING'); const [query, setQuery] = useState(''); const rows = withdrawals.filter(item => (filter === 'ALL' || item.status === filter) && (!query || `${item.id} ${item.username} ${item.destination}`.toLowerCase().includes(query.toLowerCase())));
  return <div className="admin-page"><AdminSectionHeader icon={ArrowUpFromLine} title="طلبات السحب" subtitle="نفّذ طلبات السحب أو ارفضها مع إعادة المبلغ تلقائياً عند الرفض." count={withdrawals.filter(item => item.status === 'PENDING').length} tone="amber" /><AdminFilters filter={filter} setFilter={setFilter} query={query} setQuery={setQuery} options={['PENDING', 'APPROVED', 'REJECTED', 'ALL']} />{rows.length ? <div className="request-list">{rows.map(item => <article className="request-card" key={item.id}><div className="request-main"><span className="request-icon amber"><ArrowUpFromLine className="h-5 w-5" /></span><span><strong>{item.username}</strong><small>#{item.id} • {date(item.created_at)}</small></span><span className="request-amount amber-text">-{money(item.amount)}</span><StatusBadge status={item.status} /></div><div className="request-details"><span><small>طريقة الاستلام</small><b>{item.method}</b></span><span><small>الحساب أو الهاتف</small><b className="mono">{item.destination}</b></span><span><small>ملاحظات</small><b>{item.notes || 'لا توجد ملاحظات'}</b></span></div>{item.status === 'PENDING' && <div className="request-actions"><button className="primary-button small" onClick={() => approveWithdrawal(item.id, true)}><Check className="h-4 w-4" />تأكيد التحويل</button><button className="danger-button small" onClick={() => approveWithdrawal(item.id, false)}><XCircle className="h-4 w-4" />رفض وإعادة الرصيد</button></div>}</article>)}</div> : <Empty icon={ArrowUpFromLine} text="لا توجد طلبات سحب بهذه الحالة." />}</div>;
}
function matchNeedsReview(match: Match) { return Boolean(match.opponent_id && !['OPEN', 'CANCELLED'].includes(match.status) && match.payout_status !== 'APPROVED'); }
function AdminMatchesPage() {
  const { matches } = useArena(); const [filter, setFilter] = useState('PENDING'); const [query, setQuery] = useState('');
  const rows = matches.filter(item => { const matchesFilter = filter === 'ALL' || (filter === 'PENDING' ? matchNeedsReview(item) : item.status === filter); const matchesQuery = !query || `${item.id} ${item.title} ${item.creator_name} ${item.opponent_name || ''} ${item.winner_name || ''}`.toLowerCase().includes(query.toLowerCase()); return matchesFilter && matchesQuery; });
  return <div className="admin-page"><AdminSectionHeader icon={Monitor} title="مراقبة المباريات" subtitle="راجع المواجهات، حدّد الفائز، ثم اعتمد صرف الجائزة أو علّقها عند وجود شك." count={matches.filter(matchNeedsReview).length} tone="blue" /><AdminFilters filter={filter} setFilter={setFilter} query={query} setQuery={setQuery} options={['PENDING', 'PLAYING', 'DISPUTE', 'COMPLETED', 'ALL']} />{rows.length ? <div className="request-list">{rows.map(item => <MatchReviewCardWithClaims match={item} key={item.id} />)}</div> : <Empty icon={Monitor} text="لا توجد مباريات تحتاج إلى مراجعة بهذه الحالة." />}</div>;
}
function MatchReviewCard({ match }: { match: Match }) {
  const { setMatchResult, reviewMatchPayout } = useArena(); const [winnerId, setWinnerId] = useState(match.winner_id || ''); const [note, setNote] = useState(match.payout_note || ''); const [feedback, setFeedback] = useState(''); const [busy, setBusy] = useState(false); const players = [{ id: match.creator_id, name: match.creator_name, efootballId: match.creator_efootball_id }, ...(match.opponent_id ? [{ id: match.opponent_id, name: match.opponent_name || 'اللاعب المنافس', efootballId: match.opponent_efootball_id || 'غير متوفر' }] : [])];
  const submitResult = async () => { if (!winnerId) return setFeedback('اختر الفائز قبل تسجيل النتيجة.'); setBusy(true); const ok = await setMatchResult(match.id, winnerId, note); setBusy(false); setFeedback(ok ? 'تم تسجيل النتيجة. الجائزة الآن بانتظار اعتماد الإدارة.' : 'تعذر تسجيل النتيجة. حاول مرة أخرى.'); };
  const approve = async () => { if (!match.winner_id) return setFeedback('سجّل النتيجة أولاً ثم اعتمد الجائزة.'); if (winnerId !== match.winner_id) return setFeedback('احفظ اختيار الفائز أولاً قبل اعتماد الجائزة.'); setBusy(true); const ok = await reviewMatchPayout(match.id, true, note); setBusy(false); setFeedback(ok ? 'تم اعتماد الجائزة وتسجيل العملية.' : 'تعذر اعتماد الجائزة.'); };
  const reject = async () => { if (!match.winner_id) return setFeedback('سجّل النتيجة أولاً.'); if (!note.trim()) return setFeedback('اكتب سبب تعليق أو رفض صرف الجائزة.'); setBusy(true); const ok = await reviewMatchPayout(match.id, false, note); setBusy(false); setFeedback(ok ? 'تم تعليق صرف الجائزة وفتح المباراة للمراجعة.' : 'تعذر تحديث قرار الجائزة.'); };
  return <article className="request-card match-review-card"><div className="request-main"><span className="request-icon blue"><Monitor className="h-5 w-5" /></span><span><strong>{match.title}</strong><small>#{match.id} • {match.creator_name} ضد {match.opponent_name || 'بانتظار منافس'} • {date(match.created_at || new Date().toISOString())}</small></span><StatusBadge status={match.status} />{match.payout_status && <StatusBadge status={match.payout_status} />}</div><div className="request-details"><span><small>المنصة</small><b>{match.platform}</b></span><span><small>الرهان</small><b>{money(match.stake)}</b></span><span><small>الجائزة</small><b className="amber-text">{money(match.prize)}</b></span><span><small>الفائز المسجل</small><b>{match.winner_name || 'لم يحدد بعد'}</b></span></div>{match.opponent_id ? <div className="match-review-controls"><div className="form-grid"><label className="form-field"><span>تحديد الفائز</span><select value={winnerId} onChange={event => setWinnerId(event.target.value)}><option value="">اختر اللاعب الفائز</option>{players.map(player => <option value={player.id} key={player.id}>{player.name} • {player.efootballId}</option>)}</select></label><label className="form-field"><span>ملاحظة الإدارة</span><input value={note} onChange={event => setNote(event.target.value)} placeholder="سبب القرار أو ملاحظاته" /></label></div>{feedback && <Notice type={feedback.startsWith('تم') ? 'success' : 'error'}>{feedback}</Notice>}<div className="request-actions"><button className="secondary-button small" disabled={busy} onClick={submitResult}><Save className="h-4 w-4" />{match.winner_id ? 'تحديث النتيجة' : 'تسجيل النتيجة'}</button>{match.winner_id && match.payout_status !== 'APPROVED' && <><button className="primary-button small" disabled={busy} onClick={approve}><Check className="h-4 w-4" />اعتماد دفع الجائزة</button><button className="danger-button small" disabled={busy} onClick={reject}><XCircle className="h-4 w-4" />رفض الدفع وفتح نزاع</button></>}</div></div> : <div className="quote-box">هذه المباراة بانتظار انضمام منافس قبل تسجيل النتيجة.</div>}{match.payout_status === 'APPROVED' && <div className="resolution-box"><CheckCircle2 className="h-4 w-4" />تم اعتماد صرف {money(match.prize)} للفائز {match.winner_name}.</div>}{match.payout_status === 'REJECTED' && <div className="quote-box">تم تعليق صرف الجائزة: {match.payout_note || 'بانتظار قرار جديد من الإدارة.'}</div>}</article>;
}
function MatchReviewCardWithClaims({ match }: { match: Match }) { const claimText = (claim: string | undefined, playerId: string, playerName: string) => claim ? `${claim === playerId ? 'أنا ربحت' : 'الخصم ربح'} • ${playerName}` : 'لم يرسل بعد'; return <div className="match-review-wrapper"><div className="admin-claim-summary"><span><small>تصريح {match.creator_name}</small><b>{claimText(match.creator_claim, match.creator_id, match.creator_name)}</b></span><span><small>تصريح {match.opponent_name || 'الخصم'}</small><b>{match.opponent_id ? claimText(match.opponent_claim, match.opponent_id, match.opponent_name || 'الخصم') : 'بانتظار منافس'}</b></span></div><MatchReviewCard match={match} /></div>; }
function AdminTournamentsPage() {
  const { tournaments, saveTournament, deleteTournament } = useArena(); const [query, setQuery] = useState(''); const [editorOpen, setEditorOpen] = useState(false); const [editing, setEditing] = useState<Tournament | undefined>();
  const rows = tournaments.filter(item => !query || `${item.title} ${item.platform || ''} ${item.rules}`.toLowerCase().includes(query.toLowerCase()));
  const openEditor = (item?: Tournament) => { setEditing(item); setEditorOpen(true); };
  const remove = async (item: Tournament) => { if (window.confirm(`حذف البطولة «${item.title}»؟`)) await deleteTournament(item.id); };
  return <div className="admin-page"><div className="admin-tournaments-hero"><AdminSectionHeader icon={Trophy} title="إدارة البطولات" subtitle="أنشئ بطولات عصرية وعدّل كل تفاصيلها، بما فيها صورة الغلاف والحالة." tone="amber" /><button className="primary-button" onClick={() => openEditor()}><Plus className="h-4 w-4" />إضافة بطولة</button></div><div className="admin-filters"><div className="search-box"><Search className="h-4 w-4" /><input value={query} onChange={event => setQuery(event.target.value)} placeholder="ابحث في البطولات" /></div><span className="records-count">{rows.length} بطولة</span></div>{rows.length ? <div className="admin-tournament-grid">{rows.map(item => <article className="admin-tournament-card" key={item.id}><div className="admin-tournament-media">{item.image_url ? <img src={item.image_url} alt={item.title} /> : <ImageIcon className="h-10 w-10" />}<div><StatusBadge status={item.status || 'UPCOMING'} />{item.featured && <span className="featured-label">مميزة</span>}</div></div><div className="admin-tournament-body"><div className="split-row"><div><h3>{item.title}</h3><p>{item.description || item.rules}</p></div><span className="capacity">{item.participant_count}/{item.max_players}</span></div><div className="admin-tournament-facts"><span><small>الجائزة</small><b className="amber-text">{money(item.prize_pool)}</b></span><span><small>الدخول</small><b>{money(item.entry_fee)}</b></span><span><small>المنصة</small><b>{item.platform || 'الهاتف'}</b></span><span><small>البداية</small><b>{item.start_date || 'لاحقاً'}</b></span></div><div className="admin-tournament-actions"><button className="secondary-button small" onClick={() => openEditor(item)}><Pencil className="h-3.5 w-3.5" />تعديل</button><button className="danger-button small" onClick={() => void remove(item)}><Trash2 className="h-3.5 w-3.5" />حذف</button></div></div></article>)}</div> : <Empty icon={Trophy} text="لا توجد بطولات مطابقة للبحث." />}{editorOpen && <TournamentEditorModal tournament={editing} onClose={() => setEditorOpen(false)} />}</div>;
}
function TournamentEditorModal({ tournament, onClose }: { tournament?: Tournament; onClose: () => void }) {
  const { saveTournament } = useArena(); const [draft, setDraft] = useState<TournamentDraft>(() => toTournamentDraft(tournament)); const [imageFile, setImageFile] = useState<File>(); const [error, setError] = useState(''); const update = (key: keyof TournamentDraft, value: string | number | boolean) => setDraft(old => ({ ...old, [key]: value }));
  const submit = async (event: FormEvent) => { event.preventDefault(); if (!draft.title.trim()) return setError('اكتب اسم البطولة.'); if (draft.max_players < 2) return setError('عدد اللاعبين يجب أن يكون 2 على الأقل.'); if (draft.prize_pool < 0 || draft.entry_fee < 0) return setError('القيم المالية لا يمكن أن تكون سالبة.'); const okay = await saveTournament({ ...draft, title: draft.title.trim(), rules: draft.rules.trim(), description: draft.description.trim() }, imageFile); if (!okay) return setError('تعذر حفظ البطولة. تحقق من إعداد Storage في Supabase ثم حاول مرة أخرى.'); onClose(); };
  return <Modal onClose={onClose} wide><div className="modal-heading"><span className="panel-icon amber"><Trophy className="h-5 w-5" /></span><span><h2>{tournament ? 'تعديل البطولة' : 'إضافة بطولة جديدة'}</h2><p>تحكم كامل في بيانات البطولة، الحالة، وصورة الغلاف.</p></span></div><form className="modal-body form-stack" onSubmit={submit}>{error && <Notice type="error">{error}</Notice>}<div className="form-grid"><Field label="اسم البطولة" value={draft.title} onChange={value => update('title', value)} /><Field label="المنصة" value={draft.platform} onChange={value => update('platform', value)} /></div><div className="form-grid"><Field label="قيمة الجوائز ($)" type="number" value={String(draft.prize_pool)} onChange={value => update('prize_pool', Number(value))} /><Field label="رسوم التسجيل ($)" type="number" value={String(draft.entry_fee)} onChange={value => update('entry_fee', Number(value))} /><Field label="الحد الأقصى للاعبين" type="number" value={String(draft.max_players)} onChange={value => update('max_players', Number(value))} /></div><div className="form-grid"><Field label="موعد البداية" value={draft.start_date} onChange={value => update('start_date', value)} placeholder="مثال: الجمعة، 21:00" /><Field label="موعد النهاية" value={draft.end_date} onChange={value => update('end_date', value)} placeholder="اختياري" /></div><div className="form-grid"><label className="form-field"><span>حالة البطولة</span><select value={draft.status} onChange={event => update('status', event.target.value as TournamentStatus)}><option value="UPCOMING">قادمة</option><option value="LIVE">مباشرة</option><option value="COMPLETED">مكتملة</option><option value="CANCELLED">ملغاة</option></select></label><label className="form-field"><span>صورة الغلاف من الجهاز</span><span className="file-input"><UploadCloud className="h-4 w-4" />{imageFile ? imageFile.name : 'اختر صورة'}<input type="file" accept="image/*" onChange={event => setImageFile(event.target.files?.[0])} /></span></label></div><label className="form-field"><span>رابط صورة الغلاف (اختياري)</span><input value={draft.image_url} onChange={event => update('image_url', event.target.value)} placeholder="https://..." /></label><label className="form-field"><span>وصف قصير</span><textarea rows={2} value={draft.description} onChange={event => update('description', event.target.value)} placeholder="وصف يظهر للاعبين" /></label><label className="form-field"><span>القواعد</span><textarea rows={3} value={draft.rules} onChange={event => update('rules', event.target.value)} /></label><label className="check-field"><input type="checkbox" checked={draft.featured} onChange={event => update('featured', event.target.checked)} /><span>إظهار كبطولة مميزة</span></label><button className="primary-button full"><Save className="h-4 w-4" />حفظ بيانات البطولة</button></form></Modal>;
}
function AdminSectionHeader({ icon: Icon, title, subtitle, count, tone = 'green' }: { icon: typeof Wallet; title: string; subtitle: string; count?: number; tone?: string }) { return <div className="section-admin-header"><div className="page-title"><span className={`page-icon tone-${tone}`}><Icon className="h-6 w-6" /></span><span><h2>{title}</h2><p>{subtitle}</p></span></div>{count !== undefined && <span className="header-count">{count} قيد المراجعة</span>}</div>; }
function AdminFilters({ filter, setFilter, query, setQuery, options }: { filter: string; setFilter: (value: string) => void; query: string; setQuery: (value: string) => void; options: string[] }) { return <div className="admin-filters"><div className="filter-list">{options.map(option => <button key={option} className={filter === option ? 'filter-active' : ''} onClick={() => setFilter(option)}>{statusLabel[option] || 'الكل'}</button>)}</div><div className="search-box"><Search className="h-4 w-4" /><input value={query} onChange={event => setQuery(event.target.value)} placeholder="بحث في الطلبات" /></div></div>; }

function AdminDisputesPage() {
  const { disputes } = useArena(); const [filter, setFilter] = useState('ALL'); const rows = disputes.filter(item => filter === 'ALL' || item.status === filter); return <div className="admin-page"><AdminSectionHeader icon={AlertTriangle} title="إدارة النزاعات" subtitle="راجع أدلة اللاعبين واتخذ قراراً واضحاً مع توثيق السبب." tone="red" /><AdminFilters filter={filter} setFilter={setFilter} query="" setQuery={() => undefined} options={['OPEN', 'UNDER_REVIEW', 'RESOLVED', 'REJECTED', 'ALL']} />{rows.length ? <div className="request-list">{rows.map(item => <DisputeRow item={item} key={item.id} />)}</div> : <Empty icon={AlertTriangle} text="لا توجد نزاعات في هذا القسم." />}</div>;
}
 function DisputeRow({ item }: { item: Dispute }) { const { resolveDispute } = useArena(); const [resolution, setResolution] = useState(item.resolution || ''); const [status, setStatus] = useState<Dispute['status']>(item.status); const [open, setOpen] = useState(item.status === 'OPEN'); return <article className="request-card dispute-card"><div className="request-main"><span className="request-icon red"><AlertTriangle className="h-5 w-5" /></span><span><strong>{item.subject}</strong><small>{item.username} • المباراة #{item.matchId} • {date(item.created_at)}</small></span><StatusBadge status={item.status} /><button className="icon-button" onClick={() => setOpen(!open)} aria-label="عرض التفاصيل"><ChevronDown className={`h-4 w-4 ${open ? 'rotate-180' : ''}`} /></button></div>{open && <div className="dispute-details"><div className="quote-box">{item.details}</div>{item.evidence?.length ? <div className="request-details"><span><small>الأدلة</small><span>{item.evidence.map((evidence, index) => evidence.startsWith('http') ? <a className="text-link" href={evidence} target="_blank" rel="noreferrer" key={evidence}>عرض الدليل {index + 1}</a> : <b key={evidence}>{evidence}</b>)}</span></span></div> : null}{item.resolution && <div className="resolution-box"><CheckCircle2 className="h-4 w-4" />{item.resolution}</div>}{!['RESOLVED', 'REJECTED'].includes(item.status) && <><label className="form-field"><span>قرار الإدارة</span><select value={status} onChange={event => setStatus(event.target.value as Dispute['status'])}><option value="UNDER_REVIEW">قيد التحقيق</option><option value="RESOLVED">تم الحل</option><option value="REJECTED">مرفوض</option></select></label><label className="form-field"><span>ملاحظات القرار</span><textarea rows={3} value={resolution} onChange={event => setResolution(event.target.value)} placeholder="اكتب سبب القرار بوضوح" /></label><button className="primary-button small" onClick={() => resolveDispute(item.id, status, resolution)}><Save className="h-4 w-4" />حفظ القرار</button></>}</div>}</article>; }

function AdminActivityPage() {
  const { activities } = useArena(); const [query, setQuery] = useState(''); const [category, setCategory] = useState('ALL'); const rows = activities.filter(item => (category === 'ALL' || item.category === category) && (!query || `${item.action} ${item.description} ${item.username}`.toLowerCase().includes(query.toLowerCase()))); return <div className="admin-page"><AdminSectionHeader icon={Activity} title="سجل النشاطات" subtitle="سجل موحّد لكل ما يحدث داخل المنصة، مع اسم المستخدم والوقت والتفاصيل." /><div className="admin-filters"><div className="filter-list">{['ALL', 'RECHARGE', 'WITHDRAWAL', 'MATCH', 'DISPUTE', 'ACCOUNT'].map(item => <button key={item} className={category === item ? 'filter-active' : ''} onClick={() => setCategory(item)}>{item === 'ALL' ? 'الكل' : categoryLabel(item)}</button>)}</div><div className="search-box"><Search className="h-4 w-4" /><input value={query} onChange={event => setQuery(event.target.value)} placeholder="ابحث في السجل" /></div></div><div className="panel-card"><ActivityList items={rows} /></div></div>; }
function categoryLabel(category: string) { return ({ RECHARGE: 'الشحن', WITHDRAWAL: 'السحب', MATCH: 'المباريات', DISPUTE: 'النزاعات', ACCOUNT: 'الحسابات', TOURNAMENT: 'البطولات', ADMIN: 'الإدارة' } as Record<string, string>)[category] || category; }

function AdminUsersPage() {
  const { users, adjustUser } = useArena(); const [query, setQuery] = useState(''); const [amounts, setAmounts] = useState<Record<string, string>>({}); const rows = users.filter(item => !query || `${item.username} ${item.email} ${item.efootball_id}`.toLowerCase().includes(query.toLowerCase())); return <div className="admin-page"><AdminSectionHeader icon={Users} title="إدارة المستخدمين" subtitle="راجع الحسابات وعدّل الأرصدة مع تسجيل كل عملية في السجل." /><div className="admin-filters"><div className="search-box"><Search className="h-4 w-4" /><input value={query} onChange={event => setQuery(event.target.value)} placeholder="ابحث باسم اللاعب أو بريده" /></div></div>{rows.length ? <div className="user-list">{rows.map(item => <div className="user-admin-row" key={item.id}><span className="avatar">{initials(item.username)}</span><span className="user-admin-main"><strong>{item.username}</strong><small>{item.email} • {item.efootball_id}</small></span><span className="mono green-text">{money(item.balance)}</span><div className="balance-adjust"><input type="number" value={amounts[item.id] || ''} onChange={event => setAmounts(old => ({ ...old, [item.id]: event.target.value }))} placeholder="+ / -" /><button onClick={() => { adjustUser(item.id, Number(amounts[item.id])); setAmounts(old => ({ ...old, [item.id]: '' })); }}><Save className="h-4 w-4" /></button></div></div>)}</div> : <Empty icon={Users} text="لا يوجد مستخدمون مسجلون بعد." />}</div>;
}

  function AdminSettingsPage() {
   const { settings, saveSettings } = useArena(); const [form, setForm] = useState(settings); const [saved, setSaved] = useState(false); const update = (key: string, value: string) => setForm(old => ({ ...old, [key]: value })); const submit = (event: FormEvent) => { event.preventDefault(); saveSettings(form); setSaved(true); setTimeout(() => setSaved(false), 1800); }; return <div className="admin-page"><AdminSectionHeader icon={Settings} title="إعدادات المنصة" subtitle="حدّث بيانات الدفع ونسبة العمولة ومعلومات التواصل." /><form className="settings-form panel-card" onSubmit={submit}>{saved && <Notice>تم حفظ الإعدادات بنجاح.</Notice>}<div className="settings-section"><h3>بيانات التحويل البنكي</h3><div className="form-grid"><Field label="اسم المستفيد" value={form.cih_name || ''} onChange={value => update('cih_name', value)} /><Field label="رقم الحساب / RIB" value={form.cih_rib || ''} onChange={value => update('cih_rib', value)} /></div></div><div className="settings-section"><h3>بيانات Cash Plus</h3><div className="form-grid"><Field label="اسم المستفيد" value={form.cashplus_name || ''} onChange={value => update('cashplus_name', value)} /><Field label="رقم التعريف" value={form.cashplus_cin || ''} onChange={value => update('cashplus_cin', value)} /></div></div><div className="settings-section"><h3>الإدارة والتسعير</h3><div className="form-grid"><Field label="نسبة العمولة" value={form.commission_rate || '0.10'} onChange={value => update('commission_rate', value)} /><Field label="مبالغ الشحن السريعة" value={form.recharge_amounts || '20,50,100,200,500'} onChange={value => update('recharge_amounts', value)} /></div><small className="settings-hint">اكتب المبالغ مفصولة بفواصل، مثل: 20,50,100,200,500</small></div><div className="settings-section whatsapp-settings"><h3>رابط واتساب الإدارة</h3><div className="form-grid"><Field label="الرابط المباشر" value={form.admin_whatsapp_link || DEFAULT_ADMIN_WHATSAPP_LINK} onChange={value => update('admin_whatsapp_link', value)} placeholder="https://wa.me/212..." /></div><small className="settings-hint">يُفتح هذا الرابط برسالة جاهزة عند طلب الشحن أو السحب أو تحديث المباراة. يجب الضغط على إرسال داخل WhatsApp.</small></div><button className="primary-button"><Save className="h-4 w-4" />حفظ التغييرات</button></form></div>; }

function AdminUsersDetailsPage() {
  const { users, adjustUser, setUserBanned } = useArena(); const [query, setQuery] = useState(''); const [selectedId, setSelectedId] = useState<string | null>(null); const [amounts, setAmounts] = useState<Record<string, string>>({}); const [banReason, setBanReason] = useState(''); const rows = users.filter(item => !query || `${item.username} ${item.email} ${item.efootball_id} ${item.whatsapp}`.toLowerCase().includes(query.toLowerCase())); const selected = users.find(item => item.id === selectedId);
  const change = (id: string, amount: number) => { if (!amount) return; adjustUser(id, amount); setAmounts(old => ({ ...old, [id]: '' })); };
  return <div className="admin-page"><AdminSectionHeader icon={Users} title="حسابات المستخدمين" subtitle="معلومات كاملة عن الحسابات، مع التحكم في الحالة وإدارة الرصيد." /><div className="account-toolbar"><div className="search-box"><Search className="h-4 w-4" /><input value={query} onChange={event => setQuery(event.target.value)} placeholder="ابحث بالاسم أو البريد أو المعرّف" /></div><span className="records-count">{rows.length} حساب</span></div>{rows.length ? <div className="users-layout"><div className="user-list detailed">{rows.map(item => <article className={`user-detail-card ${item.banned ? 'is-banned' : ''}`} key={item.id} onClick={() => setSelectedId(item.id)}><div className="user-card-head"><span className="avatar">{initials(item.username)}</span><span className="user-admin-main"><strong>{item.username}</strong><small>{item.email}</small></span><span className={item.banned ? 'ban-label' : 'active-label'}>{item.banned ? 'محظور' : 'نشط'}</span></div><div className="user-facts"><span><small>eFootball ID</small><b className="mono">{item.efootball_id}</b></span><span><small>واتساب</small><b className="mono">{item.whatsapp || 'غير مضاف'}</b></span><span><small>الرصيد</small><b className="green-text">{money(item.balance)}</b></span><span><small>النتائج</small><b>{item.wins} فوز / {item.losses} خسارة</b></span></div><div className="user-card-footer"><span>آخر دخول: {item.last_login ? date(item.last_login) : 'لم يسجل الدخول بعد'}</span><button className="text-link" onClick={event => { event.stopPropagation(); setSelectedId(item.id); }}>عرض التفاصيل <ArrowLeft className="h-3.5 w-3.5" /></button></div></article>)}</div>{selected && <aside className="account-drawer"><div className="drawer-heading"><span><span className="avatar large">{initials(selected.username)}</span><span><h3>{selected.username}</h3><small>{selected.email}</small></span></span><button className="icon-button" onClick={() => setSelectedId(null)} aria-label="إغلاق"><X className="h-4 w-4" /></button></div><div className="account-status"><span className={selected.banned ? 'ban-label' : 'active-label'}>{selected.banned ? 'الحساب محظور' : 'الحساب نشط'}</span><strong>{money(selected.balance)}</strong></div><div className="account-info-grid"><span><small>المعرّف الداخلي</small><b className="mono">{selected.id}</b></span><span><small>eFootball ID</small><b className="mono">{selected.efootball_id}</b></span><span><small>واتساب</small><b className="mono">{selected.whatsapp || 'غير مضاف'}</b></span><span><small>تاريخ التسجيل</small><b>{selected.created_at ? date(selected.created_at) : 'غير متوفر'}</b></span><span><small>آخر دخول</small><b>{selected.last_login ? date(selected.last_login) : 'لم يسجل الدخول'}</b></span><span><small>السجل الرياضي</small><b>{selected.wins} فوز / {selected.losses} خسارة</b></span></div><div className="balance-control"><h4>إدارة الرصيد</h4><p>يمكنك استخدام قيمة موجبة للإضافة أو سالبة للخصم.</p><div className="quick-amounts"><button onClick={() => change(selected.id, 10)}>+10</button><button onClick={() => change(selected.id, 50)}>+50</button><button onClick={() => change(selected.id, 100)}>+100</button></div><div className="balance-adjust large"><input type="number" value={amounts[selected.id] || ''} onChange={event => setAmounts(old => ({ ...old, [selected.id]: event.target.value }))} placeholder="مثال: 50 أو -20" /><button className="primary-button small" onClick={() => change(selected.id, Number(amounts[selected.id]))}><Save className="h-4 w-4" />تطبيق</button></div></div><div className="ban-control"><h4>{selected.banned ? 'إلغاء حظر الحساب' : 'حظر الحساب'}</h4>{selected.banned && selected.ban_reason && <p className="ban-reason">سبب الحظر: {selected.ban_reason}</p>}{!selected.banned && <textarea rows={2} value={banReason} onChange={event => setBanReason(event.target.value)} placeholder="سبب الحظر (اختياري)" />}{selected.banned ? <button className="primary-button full" onClick={() => { setUserBanned(selected.id, false, ''); setBanReason(''); }}><CheckCircle2 className="h-4 w-4" />إلغاء الحظر والسماح بالدخول</button> : <button className="danger-button full" onClick={() => { setUserBanned(selected.id, true, banReason); setBanReason(''); }}><ShieldAlert className="h-4 w-4" />حظر الحساب</button>}</div></aside>}</div> : <Empty icon={Users} text="لا يوجد مستخدمون مسجلون بعد." />}</div>;
}

function MomentumPage() {
  const { players, matches, tournaments } = useArena();
  const liveMatches = matches.filter(item => item.status === 'PLAYING').length;
  const activityScore = Math.min(98, 58 + matches.filter(item => item.status === 'OPEN').length * 4 + tournaments.length * 3);
  return <div className="shell page-wrap"><div className="page-header"><PageTitle icon={Zap} title="نبض الساحة" subtitle="لقطة حيّة عن اللاعبين والمواجهات التي تستحق المتابعة الآن." /><span className="status-badge status-success"><span className="online-dot" /> نشط الآن</span></div><div className="pulse-layout"><section className="panel-card"><div className="panel-heading"><span><BarChart3 className="h-4 w-4" />أفضل اللاعبين هذا الأسبوع</span><small>حسب نسبة الفوز</small></div><div className="pulse-list">{players.slice(0, 5).map((player, index) => <div className="pulse-row" key={player.id}><span className={`rank rank-${index + 1}`}>{index + 1}</span><span className="avatar">{initials(player.username)}</span><span className="pulse-player"><strong>{player.username}</strong><small>{player.wins} فوز • {player.efootball_id}</small></span><b className="green-text">{player.win_rate}%</b></div>)}</div></section><aside className="panel-card pulse-meter"><div className="panel-heading"><span><Activity className="h-4 w-4" />مؤشر الساحة</span><small>يتجدد باستمرار</small></div><strong>{activityScore}<small>/100</small></strong><div className="meter-track"><span style={{ width: `${activityScore}%` }} /></div><p>هناك {liveMatches} مباراة جارية و{matches.filter(item => item.status === 'OPEN').length} تحديات تنتظر منافساً.</p><div className="pulse-facts"><span><b>{players.length + 17}</b> لاعب في المنافسة</span><span><b>{tournaments.length + 8}</b> بطولات قادمة</span></div></aside></div><section className="panel-card pulse-callout"><div><span className="eyebrow"><span className="pulse-dot" />تحدٍّ مقترح</span><h2>الوقت مناسب لصناعة سلسلة انتصارات.</h2><p>ابدأ بمباراة قصيرة، ارفع تقييمك، ثم ادخل البطولة التالية بثقة.</p></div><Link href="/matches" className="primary-button">استكشف التحديات <ArrowLeft className="h-4 w-4" /></Link></section></div>;
}
function NotFound() { return <div className="shell page-wrap"><Empty icon={AlertCircle} text="الصفحة التي تبحث عنها غير موجودة." /><Link href="/" className="primary-button">العودة إلى الرئيسية</Link></div>; }
function AppShell() { return <ArenaProvider><PublicNavbar /><main className="main-content"><Switch><Route path="/" component={HomePage} /><Route path="/matches/:id" component={MatchDetailPageV2} /><Route path="/matches" component={MatchesPage} /><Route path="/tournaments" component={TournamentsPage} /><Route path="/leaderboard" component={LeaderboardPage} /><Route path="/momentum" component={MomentumPage} /><Route path="/profile" component={ProfilePage} /><Route path="/login"><AuthPage mode="login" /></Route><Route path="/register"><AuthPage mode="register" /></Route><Route path="/admin/:section" component={AdminPage} /><Route path="/admin" component={AdminPage} /><Route component={NotFound} /></Switch></main><Footer /></ArenaProvider>; }
export default AppShell;
